// OrderStatus is a wire enum.
type OrderStatus string

const (
	// OrderStatusPending Order has been sent to the matching engine and is pending a transition to open/filled/rejected.
	OrderStatusPending OrderStatus = "PENDING"
	// OrderStatusOpen Order is actively matching on the matching engine, could be unfilled or partially filled.
	OrderStatusOpen OrderStatus = "OPEN"
	// OrderStatusFilled Order is fully filled and hence closed. Taker Orders can transition directly from pending to filled, without going through open.
	OrderStatusFilled OrderStatus = "FILLED"
	// OrderStatusRejected Order is rejected by matching engine since if fails a particular check (See OrderRejectReason). Once an order is open, it cannot be rejected.
	OrderStatusRejected OrderStatus = "REJECTED"
	// OrderStatusCancelled Order is cancelled by the user using one of the supported APIs (See OrderRejectReason). Before an order is open, it cannot be cancelled.
	OrderStatusCancelled OrderStatus = "CANCELLED"
)

